@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700;800&family=Manrope:wght@400;500;600;700;800&display=swap');
:root{--ink:#1d302d;--muted:#75817b;--paper:#f6f3eb;--white:#fffdf8;--saffron:#ee9b3b;--green:#417a5e;--pale-green:#e8eee6;--line:#e6e3da;--red:#c95f4c;--blue:#587d8d;--shadow:0 18px 50px rgba(37,54,46,.08)}
*{box-sizing:border-box}html{min-height:100%;background:var(--paper)}body{margin:0;min-height:100vh;color:var(--ink);font-family:'DM Sans',sans-serif;-webkit-tap-highlight-color:transparent}.app-shell{width:min(1120px,100%);min-height:100vh;margin:0 auto;padding:0 56px;display:flex;flex-direction:column;position:relative;overflow:hidden}.topbar{height:88px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(47,64,55,.1);z-index:2}.brand{display:inline-flex;align-items:center;gap:12px;color:var(--ink);text-decoration:none;font-family:Manrope,sans-serif;font-size:15px;font-weight:600;letter-spacing:-.4px}.brand b{font-weight:800}.brand-comma{color:var(--saffron)}.brand-mark{width:26px;height:26px;display:flex;align-items:center;justify-content:center;gap:2px;transform:rotate(-18deg)}.brand-mark span{display:block;width:6px;border-radius:5px}.brand-mark span:nth-child(1){height:15px;background:#ee9b3b}.brand-mark span:nth-child(2){height:21px;background:#547e61}.brand-mark span:nth-child(3){height:12px;background:#78908a}.topbar-right{display:flex;align-items:center;gap:16px}.streak-pill{height:34px;padding:0 12px;border:1px solid var(--line);border-radius:20px;display:flex;align-items:center;gap:5px;font-size:12px}.streak-pill>span{color:var(--saffron);font-size:14px}.streak-pill strong{font-size:12px}.streak-pill small{color:var(--muted);font-size:11px}.icon-button{width:36px;height:36px;border:1px solid var(--line);background:transparent;color:var(--ink);border-radius:50%;font-size:17px;cursor:pointer}.icon-button.muted{color:#a7afa9}.screen{flex:1;position:relative;display:none}.screen.active{display:block}.home-screen{min-height:calc(100vh - 89px);padding:75px 0 70px;display:none;grid-template-columns:1.04fr .96fr;grid-template-rows:1fr auto;column-gap:24px}.home-screen.active{display:grid}.hero-copy{align-self:center;padding:0 0 48px;position:relative;z-index:1}.eyebrow{font-size:10px;font-weight:800;letter-spacing:1.55px;color:#77827c;display:flex;align-items:center;gap:9px}.eyebrow-dot{width:7px;height:7px;border-radius:50%;background:var(--saffron);box-shadow:0 0 0 4px rgba(238,155,59,.13)}h1,h2,p{margin-top:0}.hero-copy h1{font-family:Manrope,sans-serif;font-size:clamp(48px,6.2vw,72px);line-height:1.02;letter-spacing:-4px;margin:22px 0 18px;font-weight:700}.hero-copy h1 em,.section-heading h2 em,.result-content h2 em{font-style:normal;color:var(--green)}.hero-sub{max-width:350px;color:#75817b;font-size:15px;line-height:1.7;margin-bottom:27px}.primary-button{display:inline-flex;align-items:center;justify-content:space-between;gap:34px;border:0;border-radius:7px;background:var(--ink);color:#fffdf8;padding:0 9px 0 21px;height:52px;font:700 13px 'DM Sans',sans-serif;cursor:pointer;box-shadow:0 8px 18px rgba(29,48,45,.15);transition:transform .2s,background .2s}.primary-button:hover{transform:translateY(-2px);background:#29443e}.button-arrow{width:34px;height:34px;background:#35534a;border-radius:5px;display:grid;place-items:center;font-size:17px}.play-note{margin-top:18px;color:#88918b;font-size:11px;display:flex;gap:9px;align-items:center}.note-icon{font-size:17px;color:var(--saffron)}.play-note i{font-style:normal;color:#bbc0ba}.hero-art{position:relative;align-self:stretch;min-height:410px;display:flex;align-items:center;justify-content:center}.art-main-card{width:290px;height:360px;background:#d8e2d5;border-radius:145px 145px 11px 11px;position:relative;overflow:hidden;display:flex;align-items:center;justify-content:center;box-shadow:0 19px 42px rgba(55,83,67,.12);z-index:1}.art-main-card:before{content:'';position:absolute;inset:12px;border:1px solid rgba(255,255,255,.55);border-radius:140px 140px 6px 6px}.art-sun{position:absolute;width:185px;height:185px;border-radius:50%;background:#f1d8a4;top:10%;left:44%;opacity:.74}.art-map{width:220px;color:#668a6f;transform:translate(8px,2px);z-index:1}.art-map svg{width:100%;height:auto;filter:drop-shadow(3px 6px 0 rgba(50,82,59,.1))}.art-label{position:absolute;bottom:40px;left:36px;display:flex;align-items:center;gap:10px;font-size:8px;line-height:1.55;letter-spacing:.8px;color:#55725d}.art-label b{font-size:13px;letter-spacing:2px}.label-line{width:24px;height:1px;background:#76917a}.art-tricolor{position:absolute;right:35px;bottom:44px;width:5px;display:grid;gap:2px}.art-tricolor i{height:9px;border-radius:2px}.art-tricolor i:nth-child(1){background:#e8a047}.art-tricolor i:nth-child(2){background:#f6f3eb}.art-tricolor i:nth-child(3){background:#508065}.art-orbit{position:absolute;border:1px solid rgba(102,138,111,.17);border-radius:50%;transform:rotate(-34deg)}.orbit-one{width:400px;height:230px}.orbit-two{width:450px;height:270px;transform:rotate(34deg)}.art-card{position:absolute;background:var(--white);box-shadow:var(--shadow);z-index:2}.card-top{right:4%;top:12%;width:92px;height:99px;display:flex;flex-direction:column;justify-content:space-between;padding:12px;color:#5f7865;font-size:10px;font-weight:800;letter-spacing:1px;line-height:1.25;transform:rotate(5deg)}.tiny-star{color:var(--saffron);font-size:17px;align-self:flex-end}.card-bottom{left:1%;bottom:16%;padding:12px 15px;transform:rotate(-6deg);color:#48674f;text-align:center}.card-bottom span{font-family:serif;font-size:18px;display:block}.card-bottom small{font-size:7px;letter-spacing:1.2px;color:#8b958d}.floating-spark{position:absolute;color:#df963e}.spark-a{font-size:25px;left:9%;top:21%}.spark-b{font-size:17px;right:8%;bottom:22%;color:#5d8067}.art-caption{position:absolute;bottom:7px;right:5%;font-size:10px;color:#919992;letter-spacing:.2px}.art-caption span{color:var(--green);margin-left:7px}.home-bottom{grid-column:1/3;border-top:1px solid var(--line);padding:23px 4px 19px;display:flex;align-items:center;gap:27px}.mini-stat{display:flex;align-items:center;gap:10px}.stat-icon{width:30px;height:30px;border-radius:50%;display:grid;place-items:center;font-size:14px}.stat-icon.saffron{color:#d8872a;background:#f7e9d4}.stat-icon.green{color:#497b5b;background:#e2ebe2}.stat-icon.blue{color:#557d8b;background:#e3ebec}.mini-stat b,.mini-stat small{display:block}.mini-stat b{font-size:11px;margin-bottom:3px}.mini-stat small{font-size:10px;color:#89928c}.stat-divider{height:27px;width:1px;background:var(--line)}.home-footer{position:absolute;bottom:18px;left:0;right:0;display:flex;justify-content:space-between;color:#a6ada7;font-size:8px;letter-spacing:1.3px;font-weight:700}
/* Category picker */
.category-screen{padding:42px 0 70px;min-height:calc(100vh - 88px)}.back-button{border:0;background:transparent;color:#738079;display:inline-flex;align-items:center;gap:8px;padding:8px 0;font:600 12px 'DM Sans',sans-serif;cursor:pointer}.back-button:first-letter{font-size:18px}.section-heading{text-align:center;margin:14px 0 30px}.section-heading .eyebrow{justify-content:center}.section-heading h2,.result-content h2{font:700 clamp(32px,4vw,46px) Manrope,sans-serif;letter-spacing:-2px;margin:17px 0 8px}.section-heading p{font-size:13px;color:var(--muted);margin:0}.category-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:13px;max-width:870px;margin:0 auto}.category-card{min-height:162px;text-align:left;background:var(--white);border:1px solid #e8e5dc;border-radius:9px;padding:19px 18px 16px;cursor:pointer;color:var(--ink);position:relative;overflow:hidden;transition:transform .18s,box-shadow .18s,border .18s}.category-card:hover{transform:translateY(-3px);box-shadow:0 12px 26px rgba(37,54,46,.08);border-color:#b9c9b9}.category-icon{width:36px;height:36px;border-radius:9px;display:grid;place-items:center;font-size:19px;margin-bottom:15px}.tone-saffron{background:#f8ead6;color:#c67c29}.tone-green{background:#e4ede3;color:#4f795a}.tone-blue{background:#e4ecee;color:#527987}.tone-plum{background:#efe5ed;color:#8c6684}.tone-gold{background:#f2eddb;color:#a38637}.category-card h3{font:700 14px Manrope,sans-serif;margin:0 0 5px;letter-spacing:-.2px}.category-card p{color:#8a938c;font-size:10px;line-height:1.4;margin:0}.category-arrow{position:absolute;right:17px;bottom:15px;color:#a0aaa2;font-size:16px;transition:transform .18s}.category-card:hover .category-arrow{transform:translate(2px,-2px);color:var(--green)}.category-bottom{max-width:870px;margin:17px auto 0;display:flex;justify-content:space-between;color:#959d97;font-size:10px}
/* Gameplay */
.game-screen{padding:26px 0 32px;min-height:calc(100vh - 88px);display:flex;flex-direction:column}.game-topline{display:flex;align-items:center;justify-content:space-between}.compact{padding:0}.round-label{display:flex;align-items:center;gap:8px;font-size:9px;letter-spacing:1.2px;color:#808a83;font-weight:800}.round-dot{width:7px;height:7px;border-radius:50%;background:var(--saffron)}.game-score{background:#f1e9da;border-radius:15px;padding:7px 12px;font-size:12px;display:flex;align-items:center;gap:6px}.game-score span{color:var(--saffron)}.progress-wrap{max-width:650px;width:100%;align-self:center;margin:34px 0 19px}.progress-meta{display:flex;justify-content:space-between;margin-bottom:9px;font-size:9px;letter-spacing:1px;color:#8b958e;font-weight:700}.progress-meta b{color:var(--ink)}.progress-meta i{font-style:normal;color:#a9b0aa}.progress-track{height:4px;background:#e5e4dc;border-radius:9px;overflow:hidden}.progress-fill{width:10%;height:100%;border-radius:9px;background:linear-gradient(90deg,#eda148,#edbb6d);transition:width .35s ease}.question-card{width:min(650px,100%);align-self:center;background:var(--white);border:1px solid #ebe8df;border-radius:12px;padding:30px 34px 23px;box-shadow:0 15px 42px rgba(43,59,48,.045);position:relative}.question-kicker{display:flex;align-items:center;justify-content:space-between;color:#819087;font-size:9px;letter-spacing:1.4px;font-weight:800}.question-spark{color:var(--saffron);font-size:16px}.question-card h2{font:700 clamp(21px,3vw,27px) Manrope,sans-serif;line-height:1.38;letter-spacing:-.7px;margin:22px 0 21px;max-width:550px}.answers{display:grid;grid-template-columns:1fr 1fr;gap:10px}.answer-option{background:#fbfaf6;border:1px solid #e9e7df;border-radius:7px;min-height:54px;padding:10px 12px;display:flex;align-items:center;gap:11px;text-align:left;color:#394b43;font:600 12px 'DM Sans',sans-serif;cursor:pointer;transition:border .15s,background .15s,transform .15s}.answer-option:hover:not(:disabled){border-color:#9bb39e;background:#f5f8f2;transform:translateY(-1px)}.answer-key{width:25px;height:25px;flex:0 0 25px;display:grid;place-items:center;background:#f0eee7;border-radius:5px;color:#8c968e;font-size:10px;font-weight:800}.answer-option.correct{border-color:#75a181;background:#eef5eb;color:#345c42}.answer-option.correct .answer-key{background:#5b8b65;color:white}.answer-option.wrong{border-color:#d58b7d;background:#fbefeb;color:#8d5144}.answer-option.wrong .answer-key{background:#c96b58;color:white}.answer-option.reveal{border-color:#75a181;background:#eef5eb}.answer-option:disabled{cursor:default}.feedback{min-height:39px;margin:12px 0 1px;color:#67736c;font-size:11px;line-height:1.5}.feedback strong{color:var(--green)}.feedback.incorrect strong{color:var(--red)}.next-button{width:100%;height:45px;padding:0 14px 0 18px;border:0;border-radius:6px;background:#e7e9e2;color:#8d968e;display:flex;align-items:center;justify-content:space-between;font:700 12px 'DM Sans',sans-serif;cursor:not-allowed;transition:background .2s,color .2s}.next-button.ready{background:var(--ink);color:#fffdf8;cursor:pointer}.next-button.ready:hover{background:#35534a}.next-button span:last-child{font-size:18px}.game-foot{margin-top:auto;display:flex;justify-content:space-between;color:#a2aaa3;font-size:8px;letter-spacing:1.1px;font-weight:700;padding-top:24px}.game-foot #streakLabel{color:#ba8d4a;letter-spacing:.4px;font-size:10px}
/* Results */
.result-screen{min-height:calc(100vh - 88px);padding:30px 0 42px;display:flex;flex-direction:column}.result-content{width:min(500px,100%);margin:4px auto 0;text-align:center;position:relative;z-index:1}.result-badge{width:61px;height:61px;background:#e7eee3;border:1px solid #d7e3d5;border-radius:50%;display:grid;place-items:center;margin:0 auto 15px;color:#5f8765;font-size:28px;position:relative}.result-badge:after{content:'';position:absolute;inset:-6px;border:1px dashed #cbd9c9;border-radius:50%}.result-content>.eyebrow{justify-content:center}.result-content h2{font-size:38px;margin:14px 0 6px}.result-content>p{font-size:12px;color:#89938c;margin:0 0 21px}.score-card{position:relative;background:var(--white);border:1px solid #e7e4dc;border-radius:9px;padding:17px 23px;display:flex;align-items:center;justify-content:center;gap:24px;box-shadow:0 10px 27px rgba(43,59,48,.04);text-align:left}.score-number{white-space:nowrap}.score-number strong{font:800 38px Manrope,sans-serif;letter-spacing:-2px}.score-number span{font-size:14px;color:#9aa39c}.score-divider{width:1px;height:40px;background:var(--line)}.score-detail{display:flex;flex-direction:column;gap:7px;font-size:10px;color:#8b958e}.score-detail b{color:var(--ink);font-size:12px;margin-right:3px}.score-seal{position:absolute;right:14px;top:12px;color:#d9ddd5;font:700 12px serif;text-align:center;line-height:1.2;transform:rotate(9deg)}.score-seal small{font:700 5px 'DM Sans',sans-serif;letter-spacing:.8px}.result-actions{display:flex;justify-content:center;gap:10px;margin:17px 0}.result-actions .primary-button{height:47px}.secondary-button{border:1px solid #dedfd7;background:transparent;color:#65736a;border-radius:6px;padding:0 16px;font:700 11px 'DM Sans',sans-serif;cursor:pointer}.secondary-button:hover{background:#eeeee7}.secondary-button span{margin-left:8px}.review-list{max-height:230px;overflow:auto;text-align:left;padding:8px 14px;border:1px solid var(--line);border-radius:8px;background:#fbfaf6}.review-item{padding:10px 0;border-bottom:1px solid #edebe3;font-size:10px;line-height:1.5}.review-item:last-child{border:0}.review-item b{display:block;font-size:11px;margin-bottom:3px}.review-item span{color:#7d8981}.review-item .review-result{color:var(--green);font-weight:700}.result-footer{margin-top:auto;display:flex;justify-content:center;gap:8px;color:#a5ada6;font-size:8px;letter-spacing:1.2px;font-weight:700}.result-footer span{color:var(--saffron)}.result-confetti{position:absolute;inset:0;pointer-events:none;color:#edb366;opacity:.8}.result-confetti i{font-style:normal;position:absolute}.result-confetti i:nth-child(1){top:25%;left:11%;font-size:30px}.result-confetti i:nth-child(2){top:42%;right:12%;font-size:22px;color:#6b9371}.result-confetti i:nth-child(3){top:68%;left:16%;font-size:20px;color:#d58c45}.result-confetti i:nth-child(4){top:15%;right:21%;font-size:14px;color:#8da590}
[hidden]{display:none!important}.screen[hidden]{display:none!important}.screen.active[hidden]{display:flex!important}
@media(max-width:760px){.app-shell{padding:0 30px}.topbar{height:72px}.home-screen{min-height:calc(100vh - 72px);padding:44px 0 68px;grid-template-columns:1fr .8fr;column-gap:0}.hero-copy h1{font-size:clamp(45px,7vw,62px)}.hero-art{min-height:340px}.art-main-card{width:245px;height:315px}.art-map{width:185px}.art-sun{width:150px;height:150px}.card-top{right:0;top:14%;width:75px;height:86px;font-size:8px}.card-bottom{left:-1%;bottom:18%;padding:9px 11px}.art-caption{font-size:8px;right:0}.home-bottom{gap:17px}.mini-stat{gap:7px}.stat-icon{width:26px;height:26px}.mini-stat b{font-size:10px}.mini-stat small{font-size:9px}.category-screen{min-height:calc(100vh - 72px)}.game-screen,.result-screen{min-height:calc(100vh - 72px)}}
@media(max-width:560px){.app-shell{padding:0 21px}.topbar{height:66px}.brand{font-size:13px;gap:9px}.brand-mark{transform:scale(.9) rotate(-18deg)}.topbar-right{gap:9px}.home-screen{min-height:calc(100svh - 66px);padding:34px 0 73px;grid-template-columns:1fr;grid-template-rows:auto auto}.hero-copy{padding:4px 0 0}.hero-copy .eyebrow{font-size:9px}.hero-copy h1{font-size:51px;letter-spacing:-3px;margin:18px 0 12px}.hero-sub{font-size:13px;line-height:1.55;max-width:330px;margin-bottom:18px}.primary-button{height:47px}.play-note{margin-top:12px}.hero-art{min-height:300px;max-height:310px;margin-top:8px}.art-main-card{width:208px;height:270px;border-radius:110px 110px 9px 9px}.art-map{width:160px}.art-label{bottom:28px;left:26px}.art-tricolor{right:25px;bottom:29px}.art-sun{width:130px;height:130px;top:9%;left:40%}.orbit-one{width:320px;height:210px}.orbit-two{width:350px;height:220px}.card-top{right:3%;top:12%;width:67px;height:75px;padding:9px;font-size:7px}.card-bottom{left:3%;bottom:14%;padding:8px 9px}.card-bottom span{font-size:15px}.card-bottom small{font-size:6px}.spark-a{left:7%;top:15%;font-size:18px}.spark-b{right:8%;bottom:18%;font-size:14px}.art-caption{bottom:0;right:5%;font-size:8px}.home-bottom{grid-column:1;padding:13px 0 10px;justify-content:space-between;gap:8px}.mini-stat{gap:6px}.stat-icon{width:24px;height:24px;font-size:11px}.mini-stat b{font-size:9px}.mini-stat small{font-size:8px}.stat-divider{height:22px}.home-footer{bottom:12px;font-size:7px;letter-spacing:.8px}.category-screen{padding:27px 0 58px;min-height:calc(100svh - 66px)}.section-heading{margin:13px 0 23px}.section-heading h2{font-size:34px;margin:13px 0 6px}.category-grid{grid-template-columns:1fr 1fr;gap:9px}.category-card{min-height:145px;padding:14px 12px 13px}.category-icon{width:32px;height:32px;font-size:17px;margin-bottom:12px}.category-card h3{font-size:12px}.category-card p{font-size:9px;max-width:130px}.category-arrow{right:12px;bottom:11px}.category-bottom{font-size:8px;margin-top:13px}.game-screen{padding:20px 0 22px;min-height:calc(100svh - 66px)}.progress-wrap{margin:28px 0 15px}.question-card{padding:23px 18px 17px}.question-card h2{font-size:21px;margin:17px 0 17px}.answers{grid-template-columns:1fr;gap:8px}.answer-option{min-height:49px;font-size:11px}.answer-key{width:23px;height:23px;flex-basis:23px}.feedback{min-height:34px;margin-top:9px;font-size:10px}.next-button{height:43px}.game-foot{font-size:7px;letter-spacing:.6px;padding-top:16px}.game-foot #streakLabel{font-size:9px}.round-label{font-size:8px}.result-screen{min-height:calc(100svh - 66px);padding:20px 0 27px}.result-content{margin-top:10px}.result-badge{width:54px;height:54px;font-size:24px;margin-bottom:13px}.result-content h2{font-size:32px}.score-card{padding:15px 17px;gap:17px}.score-number strong{font-size:34px}.score-seal{right:10px;top:9px}.result-confetti i:nth-child(1){left:2%;top:24%}.result-confetti i:nth-child(2){right:2%;top:43%}.result-confetti i:nth-child(3){left:5%;top:74%}.result-confetti i:nth-child(4){right:14%;top:11%}}
@media(max-height:700px) and (min-width:561px){.home-screen{padding-top:35px;padding-bottom:58px}.hero-art{min-height:330px}.art-main-card{height:300px;width:245px}.category-screen{padding-top:25px}.section-heading{margin:8px 0 20px}.category-card{min-height:145px}.game-screen{padding-top:18px}.progress-wrap{margin:20px 0 12px}.question-card{padding-top:22px}.result-content{margin-top:0}}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{scroll-behavior:auto!important;transition:none!important}}

const categories = [
  { id: 'ancient', icon: '⌂', tone: 'saffron', title: 'Ancient & medieval', desc: 'Dynasties, ideas & empires', eyebrow: 'OLD SOUL, BIG STORIES' },
  { id: 'freedom', icon: '✊', tone: 'green', title: 'Freedom movement', desc: 'The long road to independence', eyebrow: 'THE ROAD TO 1947' },
  { id: 'modern', icon: '◉', tone: 'blue', title: 'India, made modern', desc: 'A republic takes shape', eyebrow: 'A NATION IN THE MAKING' },
  { id: 'current', icon: '⌁', tone: 'plum', title: 'Current affairs', desc: 'Big moments, recent years', eyebrow: 'INDIA RIGHT NOW' },
  { id: 'mixed', icon: '✳', tone: 'gold', title: 'A bit of everything', desc: 'A surprise tour of India', eyebrow: 'THE GRAND TOUR' }
];

// Facts in the current affairs set are anchored to their stated years so they remain useful over time.
const bank = {
  ancient: [
    { q: 'Which ancient Indian city is famous for its carefully planned grid and advanced drainage?', options: ['Harappa', 'Pataliputra', 'Madurai', 'Taxila'], answer: 0, era: 'INDUS VALLEY CIVILIZATION', why: 'Harappa was one of the major urban centres of the Indus Valley Civilization, known for planned streets and drainage.' },
    { q: 'Who is traditionally credited with writing the Arthashastra?', options: ['Kalidasa', 'Chanakya (Kautilya)', 'Banabhatta', 'Panini'], answer: 1, era: 'MAURYAN INDIA', why: 'The Arthashastra, a treatise on statecraft, is traditionally attributed to Kautilya, also known as Chanakya.' },
